/**
 * Africa's Talking SDK Wrapper
 * Handles SMS, IVR, and Call functionalities
 */

const AfricasTalking = require('africastalking');

class AfricasTalkingService {
  constructor(config) {
    this.apiKey = config.apiKey;
    this.username = config.username;
    this.initializeClient();
  }

  initializeClient() {
    const africastalking = AfricasTalking({
      apiKey: this.apiKey,
      username: this.username
    });

    this.sms = africastalking.SMS;
    this.voice = africastalking.VOICE;
  }

  /**
   * Send SMS message
   * @param {string} phoneNumber - Recipient phone number
   * @param {string} message - Message content
   * @param {string} shortCode - Optional short code
   * @returns {Promise}
   */
  async sendSMS(phoneNumber, message, shortCode = null) {
    try {
      const options = {
        to: this.formatPhoneNumber(phoneNumber),
        message: message
      };

      if (shortCode) {
        options.from = shortCode;
      }

      const result = await this.sms.send(options);
      return {
        success: true,
        data: result,
        messageId: result.SMSMessageData?.Recipients?.[0]?.messageId
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Send IVR (voice) message
   * @param {string} phoneNumber - Recipient phone number
   * @param {Object} options - IVR options {audioUrl, ttsText, callerId}
   * @returns {Promise}
   */
  async sendIVR(phoneNumber, options) {
    try {
      const callOptions = {
        to: this.formatPhoneNumber(phoneNumber),
        from: options.callerId || null
      };

      // If audioUrl is provided, use it; otherwise use TTS
      if (options.audioUrl) {
        callOptions.url = options.audioUrl;
      } else if (options.ttsText) {
        callOptions.text = options.ttsText;
      } else {
        throw new Error('Either audioUrl or ttsText must be provided');
      }

      const result = await this.voice.call(callOptions);
      return {
        success: true,
        data: result,
        sessionId: result.data?.sessionId || result.sessionId
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Initialize outgoing call with callback
   * @param {string} phoneNumber - Recipient phone number
   * @param {string} callerId - Caller ID
   * @param {string} webhookUrl - Webhook URL for callbacks
   * @returns {Promise}
   */
  async initiateCallWithCallback(phoneNumber, callerId, webhookUrl) {
    try {
      const result = await this.voice.call({
        to: this.formatPhoneNumber(phoneNumber),
        from: callerId,
        record: true
      });

      return {
        success: true,
        data: result,
        sessionId: result.data?.sessionId || result.sessionId
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Format phone number to E.164 format
   * @param {string} phoneNumber - Phone number to format
   * @returns {string}
   */
  formatPhoneNumber(phoneNumber) {
    // Remove any non-numeric characters
    let cleaned = phoneNumber.replace(/\D/g, '');

    // If number doesn't start with +, add country code
    if (!phoneNumber.startsWith('+')) {
      // Default to Rwanda country code (+250) if not specified
      if (cleaned.length === 9) {
        cleaned = '250' + cleaned;
      } else if (cleaned.length === 10 && !cleaned.startsWith('0')) {
        cleaned = '250' + cleaned;
      } else if (cleaned.length === 10 && cleaned.startsWith('0')) {
        cleaned = '250' + cleaned.substring(1);
      }
    } else {
      cleaned = cleaned.substring(0);
    }

    return '+' + cleaned;
  }

  /**
   * Update credentials
   * @param {Object} config - New configuration
   */
  updateCredentials(config) {
    this.apiKey = config.apiKey;
    this.username = config.username;
    this.initializeClient();
  }
}

module.exports = AfricasTalkingService;